package com.causalops.demo;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import java.util.*;
@SpringBootApplication @RestController public class DemoApplication {final RestClient http=RestClient.create();static volatile int latency=0;public static void main(String[]x){SpringApplication.run(DemoApplication.class,x);}@GetMapping("/orders/{id}") Object order(@PathVariable String id)throws Exception{delay();var inv=http.get().uri(System.getenv().getOrDefault("INVENTORY_URL","http://inventory-service:8080")+"/inventory/sku-demo").retrieve().body(Map.class);var pay=http.post().uri(System.getenv().getOrDefault("PAYMENT_URL","http://payment-service:8080")+"/payments").body(Map.of("orderId",id)).retrieve().body(Map.class);return Map.of("id",id,"inventory",inv,"payment",pay);}@PostMapping("/internal/fault") Object fault(@RequestBody Map<String,Object>x){latency=((Number)x.getOrDefault("latencyMs",0)).intValue();return Map.of("latencyMs",latency);}@GetMapping("/business") Object business()throws Exception{return order("demo");}void delay()throws Exception{if(latency>0)Thread.sleep(latency);}}
